import collections
from dataclasses import dataclass
from typing import Any, Callable, Dict, List, Optional, Tuple

@dataclass
class TaskResult:
    status: str
    result: Any = None
    error: Optional[str] = None
    func: Optional[str] = None

class TaskRunner:
    def __init__(self) -> None:
        self._tasks: List[Tuple[Callable[..., Any], Tuple[Any, ...], Dict[str, Any]]] = []
        self._results: List[TaskResult] = []

    def add_task(self, func: Callable[..., Any], *args: Any, **kwargs: Any) -> None:
        self._tasks.append((func, args, kwargs))

    def run(self) -> List[TaskResult]:
        self._results.clear()
        for func, args, kwargs in self._tasks:
            try:
                result = func(*args, **kwargs)
                self._results.append(TaskResult(status="ok", result=result))
            except Exception as exc:
                self._results.append(
                    TaskResult(status="error", error=str(exc), func=func.__name__)
                )
        return self._results

    @property
    def errors(self) -> List[TaskResult]:
        return [r for r in self._results if r.status == "error"]

    @property
    def successes(self) -> List[TaskResult]:
        return [r for r in self._results if r.status == "ok"]

    @property
    def summary(self) -> Dict[str, int]:
        return collections.Counter(r.status for r in self._results) | {"total": len(self._results)}
